SPEC = {'pep6': {'layout': 'dict', 'sep': '', 'cut': 1, 'key': 'reverse', 'types': {'z': 's', 'e': 'i', 'b': 'f', 'q': 'd'}, 'dec': {'s': 'reverse', 'i': 'sep.', 'f': 'float', 'd': 'compact'}, 'true': None, 'null': '!'}, 'vel6': {'layout': 'triples', 'sep': '', 'cut': 0, 'key': 'lower', 'types': {'d': 's', 'k': 'i', 'w': 'd', 'v': 'f'}, 'dec': {'s': 'reverse', 'i': 'hex', 'f': 'comma', 'd': 'iso'}, 'true': None, 'null': '!'}}
DEC = {
    'd': {'compact': lambda v: v[0:4] + '-' + v[4:6] + '-' + v[6:8], 'dmy': lambda v: v[6:10] + '-' + v[3:5] + '-' + v[0:2], 'iso': lambda v: v, 'mdy': lambda v: v[6:10] + '-' + v[0:2] + '-' + v[3:5]},
    'f': {'comma': lambda v: float(v.replace(',', '.')), 'float': lambda v: float(v), 'percent': lambda v: round(float(v[:-1]) / 100.0, 3), 'permille': lambda v: int(v[:-2]) / 1000.0},
    'i': {'hex': lambda v: int(v, 16), 'int': lambda v: int(v), 'milli': lambda v: int(v[:-1]) // 1000, 'paren': lambda v: (-int(v[1:-1]) if v[:1] == '(' else int(v)), 'sep ': lambda v: int(v.replace(' ', '')), 'sep,': lambda v: int(v.replace(',', '')), 'sep.': lambda v: int(v.replace('.', '')), 'sep_': lambda v: int(v.replace('_', ''))},
    's': {'lower': lambda v: v.lower(), 'reverse': lambda v: v[::-1], 'same': lambda v: v, 'strip': lambda v: v.strip(), 'unquote': lambda v: v[1:-1]},
}


def _fields(p, data):
    if p['layout'] == 'triples':
        return [(k, t, v) for k, t, v in data]
    if p['layout'] == 'dict':
        items = list(data.items())
    else:
        items = [f.split('=', 1) for f in data.split(p['sep'])] if data else []
    return [(kt[:-2], kt[-1], v) for kt, v in items]


def solve(args, caller):
    out = []
    for row in args['rows']:
        p = SPEC.get(row.get('src'))
        if p is None:
            out.append({})
            continue
        rec = {}
        for k, tag, v in _fields(p, row['data']):
            k = k[p['cut']:]
            k = k[::-1] if p['key'] == 'reverse' else k.lower()
            ty = p['types'].get(tag)
            if v == p['null'] or ty is None:
                rec[k] = None
            elif ty == 'b':
                rec[k] = v == p['true']
            else:
                try:
                    rec[k] = DEC[ty][p['dec'][ty]](v)
                except (ValueError, IndexError):
                    rec[k] = None
        out.append(rec)
    return {'records': out}
